def evaluate_canary(canary_err: float, base_err: float, canary_p99: float, base_p99: float) -> str:
    if canary_err > max(0.01, base_err * 2.0) or canary_p99 > base_p99 * 1.5:
        return 'ROLLBACK'
    return 'PROMOTE'
