```java
public RolloutAction evaluate(double canaryErr, double baseErr, double canaryP99, double baseP99) {
    if (canaryErr > Math.max(0.01, baseErr * 2.0) || canaryP99 > baseP99 * 1.5) return RolloutAction.ROLLBACK;
    return RolloutAction.PROMOTE;
}
